  let total = 0;
  const stack = [[root, 0]];
  while (stack.length > 0) {
    const [node, prev] = stack.pop();
    const value = prev * 2 + node.val;     // shift left, append this bit
    if (node.left === null && node.right === null) total += value;
    if (node.right) stack.push([node.right, value]);
    if (node.left) stack.push([node.left, value]);
  }
  return total;
}

