public int sumRootToLeaf(TreeNode root) {
    int total = 0;
    Deque<Object[]> stack = new ArrayDeque<>();
    stack.push(new Object[]{root, 0});
    while (!stack.isEmpty()) {
        Object[] top = stack.pop();
        TreeNode node = (TreeNode) top[0];
        int value = (int) top[1] * 2 + node.val;    // shift left, append this bit
        if (node.left == null && node.right == null) total += value;
        if (node.right != null) stack.push(new Object[]{node.right, value});
        if (node.left != null) stack.push(new Object[]{node.left, value});
    }
    return total;
}

int sumRootToLeaf(TreeNode* root) {
    int total = 0;
    stack<pair<TreeNode*, int>> st;
    st.push({root, 0});
    while (!st.empty()) {
        auto [node, prev] = st.top();
        st.pop();
        int value = prev * 2 + node->val;   // shift left, append this bit
        if (!node->left && !node->right) total += value;
        if (node->right) st.push({node->right, value});
        if (node->left) st.push({node->left, value});
    }
    return total;
}

